//! 📦️ Variable stock uses the same Source-owned escrow row and nominal claim authority.
use super::*;
type A=OriginalReturnEscrowAmounts;
/// 🎟️ A real Source row owns this non-cloneable stock until every effect and observation returns.
pub struct OriginalReturnStockClaim<I:OriginalReturnOrigin>{credit:OriginalReturnClaimCredit<I>,pending:bool}
impl<I:OriginalReturnOrigin> OriginalReturnStockClaim<I>{
 pub fn terminal_is_empty(&self)->bool{self.credit.terminal_is_empty()&&!self.pending}
 pub fn serial(&self)->u64{self.credit.serial}
 pub fn source(&self)->usize{self.credit.source}
}
impl<I:OriginalReturnOrigin> Drop for OriginalReturnStockClaim<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original stock claim retains its Source effects")}}
/// 🧾️ Applied stock remains unobserved until its actual receiving Source accepts this original witness.
pub struct OriginalReturnStockWitness<I:OriginalReturnOrigin>{source:usize,serial:u64,budget:usize,progress:P,work:u64,done:bool,received:bool,_origin:std::marker::PhantomData<fn()->I>}
impl<I:OriginalReturnOrigin> OriginalReturnStockWitness<I>{pub fn progress(&self)->P{self.progress}pub fn work(&self)->u64{self.work}pub fn terminal_is_empty(&self)->bool{self.received}}
impl<I:OriginalReturnOrigin> Drop for OriginalReturnStockWitness<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.received,"original stock witness requires its actual Source observer")}}
fn add(a:A,b:A)->Result<A,ValueError>{Ok(A{items:a.items.checked_add(b.items).ok_or_else(bad)?,copy_bytes:a.copy_bytes.checked_add(b.copy_bytes).ok_or_else(bad)?,work:a.work.checked_add(b.work).ok_or_else(bad)?,release_bytes:a.release_bytes.checked_add(b.release_bytes).ok_or_else(bad)?,capacity_bytes:a.capacity_bytes.checked_add(b.capacity_bytes).ok_or_else(bad)?})}
fn sub(a:A,b:A)->Result<A,ValueError>{Ok(A{items:a.items.checked_sub(b.items).ok_or_else(bad)?,copy_bytes:a.copy_bytes.checked_sub(b.copy_bytes).ok_or_else(bad)?,work:a.work.checked_sub(b.work).ok_or_else(bad)?,release_bytes:a.release_bytes.checked_sub(b.release_bytes).ok_or_else(bad)?,capacity_bytes:a.capacity_bytes.checked_sub(b.capacity_bytes).ok_or_else(bad)?})}
fn bad()->ValueError{refused("original stock claim changed Source, order or held currencies")}
fn native(value:u64)->Result<usize,ValueError>{usize::try_from(value).map_err(|_|bad())}
fn progress(a:A)->Result<P,ValueError>{Ok(P{copied_items:native(a.items)?,copied_bytes:native(a.copy_bytes)?,retained_capacity_bytes:native(a.capacity_bytes)?,released_bytes:native(a.release_bytes)?})}
/// 📏️ Quotes the actual row, token placement and all five held-counter updates.
pub fn original_return_stock_claim_copy_bytes<I:OriginalReturnOrigin>()->usize{std::mem::size_of::<OriginalReturnEscrowRow>()+std::mem::size_of::<Option<OriginalReturnStockClaim<I>>>()+3*std::mem::size_of::<u64>()+2*std::mem::size_of::<u8>()+4*std::mem::size_of::<usize>()}

/// 📏️ Prices actual escrow/claim/witness control changes separately from the caller's physical body.
pub fn original_return_stock_settlement_copy_bytes<I:OriginalReturnOrigin>(done:bool,local:bool)->usize{2*std::mem::size_of::<A>()+2*std::mem::size_of::<u64>()+4*std::mem::size_of::<usize>()+3*std::mem::size_of::<bool>()+std::mem::size_of::<Option<OriginalReturnStockWitness<I>>>()+if done{3*std::mem::size_of::<bool>()+2*std::mem::size_of::<u8>()+if local{std::mem::size_of::<u32>()}else{0}}else{0}}
/// 📏️ Quotes the same row held amount, revision and five Source-held counters.
pub fn original_return_stock_top_up_copy_bytes()->usize{std::mem::size_of::<A>()+2*std::mem::size_of::<u64>()+std::mem::size_of::<u8>()+3*std::mem::size_of::<usize>()}
impl<I:OriginalReturnOrigin> OriginalReturnBudget<I>{
 fn stock_identity(&self,claim:&OriginalReturnStockClaim<I>)->Result<OriginalReturnEscrowIdentity,ValueError>{let origin=self.origin.ok_or_else(bad)?;if origin.recipient_identity()!=self as*const Self as usize||claim.credit.source!=origin.source_identity(){return Err(bad())}let row=self.table.as_ref().and_then(|table|table.row_at(claim.credit.slot,claim.credit.serial)).ok_or_else(bad)?;if row.identity.source!=origin.source_identity()as u64||row.identity.recipient!=origin.recipient_identity()as u64{return Err(bad())}Ok(row.identity)}
 /// 🪙️ Mints only against the same admitted budget and actual preborn destination.
 pub fn claim_stock(&mut self,destination:usize,extent:usize,epoch:u64,held:A)->Result<Option<OriginalReturnStockClaim<I>>,ValueError>{
  let origin=self.origin.ok_or_else(bad)?;if held==A::default()||origin.recipient_identity()!=self as*const Self as usize||destination==0||self.delivery==OriginalReturnDelivery::CoreWireSnapshot&&epoch==0{return Err(bad())}
  let(g,fuel)=self.remaining()?;let p=progress(held)?;let copy=original_return_stock_claim_copy_bytes::<I>();
  if g.maximum_items<p.copied_items.checked_add(1).ok_or_else(bad)?||g.maximum_copy_bytes<p.copied_bytes.checked_add(copy).ok_or_else(bad)?||g.maximum_capacity_bytes<p.retained_capacity_bytes||g.maximum_release_bytes<p.released_bytes||g.maximum_depth==0||fuel<held.work.checked_add(1).ok_or_else(bad)?{return Err(bad())}
  let serial=self.serial.checked_add(1).ok_or_else(bad)?;let claims=self.claims.checked_add(1).ok_or_else(bad)?;let items=self.held_items.checked_add(p.copied_items).ok_or_else(bad)?;let copies=self.held_copy_bytes.checked_add(p.copied_bytes).ok_or_else(bad)?;let capacity=self.held_capacity_bytes.checked_add(p.retained_capacity_bytes).ok_or_else(bad)?;let release=self.held_release_bytes.checked_add(p.released_bytes).ok_or_else(bad)?;let work=self.held_fuel.checked_add(held.work).ok_or_else(bad)?;
  let identity=OriginalReturnEscrowIdentity{source:origin.source_identity()as u64,source_birth:self.birth,recipient:origin.recipient_identity()as u64,destination:destination as u64,extent:extent as u64,serial,origin_epoch:epoch};
  let Some(slot)=self.table.as_mut().ok_or_else(bad)?.reserve(identity,held)?else{return Ok(None)};
  self.serial=serial;self.claims=claims;self.held_items=items;self.held_copy_bytes=copies;self.held_capacity_bytes=capacity;self.held_release_bytes=release;self.held_fuel=work;
  Ok(Some(OriginalReturnStockClaim{credit:OriginalReturnClaimCredit{data:OriginalReturnClaimState{source:origin.source_identity(),serial,slot,local:self.delivery==OriginalReturnDelivery::LocalWitness,capture:false,receive:false,capture_observed:false,receive_observed:false,live:true},_origin:std::marker::PhantomData},pending:false}))
 }
 /// 📈️ Grows this exact live loan from genuinely unheld Source stock, never another tranche.
 pub fn top_up_stock(&mut self,claim:&OriginalReturnStockClaim<I>,destination:usize,extent:usize,additional:A)->Result<(),ValueError>{
  if claim.pending||!claim.credit.live||additional==A::default(){return Err(bad())}self.qualify_stock_destination(claim,destination,extent)?;let identity=self.stock_identity(claim)?;let(g,fuel)=self.remaining()?;let p=progress(additional)?;if g.maximum_items<p.copied_items.checked_add(1).ok_or_else(bad)?||g.maximum_copy_bytes<p.copied_bytes.checked_add(original_return_stock_top_up_copy_bytes()).ok_or_else(bad)?||g.maximum_capacity_bytes<p.retained_capacity_bytes||g.maximum_release_bytes<p.released_bytes||g.maximum_depth==0||fuel<additional.work.checked_add(1).ok_or_else(bad)?{return Err(bad())}
  let items=self.held_items.checked_add(p.copied_items).ok_or_else(bad)?;let copy=self.held_copy_bytes.checked_add(p.copied_bytes).ok_or_else(bad)?;let capacity=self.held_capacity_bytes.checked_add(p.retained_capacity_bytes).ok_or_else(bad)?;let release=self.held_release_bytes.checked_add(p.released_bytes).ok_or_else(bad)?;let work=self.held_fuel.checked_add(additional.work).ok_or_else(bad)?;self.table.as_mut().ok_or_else(bad)?.top_up(identity,additional)?;self.held_items=items;self.held_copy_bytes=copy;self.held_capacity_bytes=capacity;self.held_release_bytes=release;self.held_fuel=work;Ok(())
 }
 /// 📍️ Rebinds this exact live claim to the carrier that now holds it; only the claim's own current destination may move.
 pub fn rebind_stock_destination(&mut self,claim:&OriginalReturnStockClaim<I>,from:usize,to:usize,extent:usize)->Result<(),ValueError>{if claim.pending||!claim.credit.live{return Err(bad())}let identity=self.stock_identity(claim)?;if identity.destination!=from as u64{return Err(bad())}self.table.as_mut().ok_or_else(bad)?.rebind(identity,to as u64,extent as u64)?;Ok(())}
 /// 🧷️ Qualifies a concrete live destination without treating its address as authority.
 pub fn qualify_stock_destination(&self,claim:&OriginalReturnStockClaim<I>,destination:usize,extent:usize)->Result<(),ValueError>{let identity=self.stock_identity(claim)?;if identity.destination!=destination as u64||identity.extent!=extent as u64{return Err(bad())}Ok(())}
 /// 🔍️ Borrows actual remaining row stock without issuing another loan.
 pub fn stock_remaining(&self,claim:&OriginalReturnStockClaim<I>)->Result<A,ValueError>{self.stock_identity(claim)?;let row=self.table.as_ref().unwrap().row_at(claim.credit.slot,claim.credit.serial).unwrap();sub(row.held,add(row.redeemed,row.released)?)}
 /// 📊️ Borrows actual cumulative row receipts without creating a new settlement authority.
 pub fn stock_receipts(&self,claim:&OriginalReturnStockClaim<I>)->Result<(A,A,A),ValueError>{self.stock_identity(claim)?;let row=self.table.as_ref().unwrap().row_at(claim.credit.slot,claim.credit.serial).unwrap();Ok((row.held,row.redeemed,row.released))}
 /// 🧮️ Cumulative actual and unused receipts cannot debit the same work twice.
 pub fn settle_stock(&mut self,claim:&mut OriginalReturnStockClaim<I>,actual:A,unused:A)->Result<Option<OriginalReturnStockWitness<I>>,ValueError>{
  if claim.pending||!claim.credit.live{return Err(bad())}let identity=self.stock_identity(claim)?;let row=*self.table.as_ref().unwrap().row_at(claim.credit.slot,claim.credit.serial).unwrap();let delta=sub(actual,row.redeemed)?;let released=sub(unused,row.released)?;let moved=add(delta,released)?;sub(row.held,add(actual,unused)?)?;if moved==A::default(){return Ok(None)}
  let p=progress(delta)?;let moved_p=progress(moved)?;let spent=self.spent.checked_add(p)?;let work=self.work.checked_add(u128::from(delta.work)).ok_or_else(bad)?;let held_items=self.held_items.checked_sub(moved_p.copied_items).ok_or_else(bad)?;let held_copy=self.held_copy_bytes.checked_sub(moved_p.copied_bytes).ok_or_else(bad)?;let held_capacity=self.held_capacity_bytes.checked_sub(moved_p.retained_capacity_bytes).ok_or_else(bad)?;let held_release=self.held_release_bytes.checked_sub(moved_p.released_bytes).ok_or_else(bad)?;let held_fuel=self.held_fuel.checked_sub(moved.work).ok_or_else(bad)?;
  let mut proposal=self.snapshot();proposal.spent=spent;proposal.work=work;proposal.held_items=usize::from(held_items);proposal.held_copy_bytes=held_copy;proposal.held_capacity_bytes=held_capacity;proposal.held_release_bytes=held_release;proposal.held_fuel=held_fuel;if !proposal.conserved(){return Err(bad())}
  self.table.as_mut().unwrap().redeem(identity,delta,released)?;let done=self.table.as_ref().unwrap().row_at(claim.credit.slot,claim.credit.serial).unwrap().tombstone;
  self.spent=spent;self.work=work;self.held_items=held_items;self.held_copy_bytes=held_copy;self.held_capacity_bytes=held_capacity;self.held_release_bytes=held_release;self.held_fuel=held_fuel;claim.pending=true;
  if done{self.claims-=1;claim.credit.data.live=false;claim.credit.data.capture_observed=true;claim.credit.data.receive_observed=true;}
  Ok(Some(OriginalReturnStockWitness{source:claim.credit.source,serial:claim.credit.serial,budget:self as*const Self as usize,progress:p,work:delta.work,done,received:false,_origin:std::marker::PhantomData}))
 }
 /// 👁️ Confirms only the actual same-Source observer after its held effects were accepted.
 pub fn acknowledge_stock(&mut self,claim:&mut OriginalReturnStockClaim<I>,witness:&mut OriginalReturnStockWitness<I>)->Result<(),ValueError>{self.qualify_stock_observation(claim,witness)?;if witness.done&&claim.credit.local{let identity=self.stock_identity(claim)?;self.table.as_mut().unwrap().mark_local_received(identity)?}witness.received=true;claim.pending=false;Ok(())}
 pub fn qualify_stock_observation(&self,claim:&OriginalReturnStockClaim<I>,witness:&OriginalReturnStockWitness<I>)->Result<(),ValueError>{self.stock_identity(claim)?;if !claim.pending||witness.received||witness.budget!=self as*const Self as usize||witness.source!=claim.credit.source||witness.serial!=claim.credit.serial{return Err(bad())}Ok(())}
}

